import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.Bb5YUzRP.js";import{Ba as i,Ga as a,Ha as o,Ka as s,La as c,Ra as l,Ua as u,Va as d,Wa as f,za as p}from"./chunks/assets.DMxVpLII.js";var m=JSON.parse(`{"title":"Downloads","description":"","frontmatter":{},"headers":[],"relativePath":"downloads.md","filePath":"downloads.md"}`),h={name:`downloads.md`},g=s+` 1x, `+a+` 2x`,_=f+` 1x, `+u+` 2x`,v=o+` 1x, `+d+` 2x`,y=i+` 1x, `+p+` 2x`,b=l+` 1x, `+c+` 2x`;function x(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="downloads" tabindex="-1">Downloads <a class="header-anchor" href="#downloads" aria-label="Permalink to “Downloads”">​</a></h1><p>The module allows you to download several files in order to produce the design.</p><h2 id="svg-download" tabindex="-1">SVG Download <a class="header-anchor" href="#svg-download" aria-label="Permalink to “SVG Download”">​</a></h2><p>You can download the production SVG from the backoffice order page or from the carts page</p><p><img src="/webp/sell-menu.jpg-90-1794236257108.webp" srcset="`+g+`" alt="Sell menu" title="" width="420" height="424" loading="lazy" style="width:210px;"></p><p>The module will display each design summary like this</p><p><img src="/webp/bo-summary.jpg-90-1794236256938.webp" srcset="`+_+`" alt="Bo summary" title="" width="1586" height="1474" loading="lazy" style="width:793px;"></p><p>Click the button <img src="/webp/svg-download-zip.jpg-90-1794236257128.webp" srcset="`+v+`" alt="Svg download zip" title="" width="318" height="70" loading="lazy" style="width:159px;"> to download the SVG file and the files that are related to the design in a single zip archive.</p><p>The zip will contain different folders for the different design sides</p><p><img src="/webp/zip.png-90-1794236257180.webp" srcset="`+y+`" alt="Zip" title="" width="1550" height="694" loading="lazy" style="width:775px;"></p><div class="tip custom-block"><p class="custom-block-title">Opening the SVG files</p><p>To open the SVG files, you need to use <a href="https://inkscape.org/" target="_blank" rel="noreferrer"><img src="/webp/inkscape-logo.svg-90-1794236257036.webp" srcset="`+b+`" alt="Inkscape logo" title="" width="128" height="128" loading="lazy" style="width:64px;"> inkscape</a> because it&#39;s the only program that is compatible with browsers in terms of SVG support.</p></div><p>You can also use inkscape to convert the <code>SVG</code> to <code>PDF</code> if you want to open them in other programs like Corel or illustrator.</p><h2 id="server-software" tabindex="-1">Server software <a class="header-anchor" href="#server-software" aria-label="Permalink to “Server software”">​</a></h2><p>The SVG download works on any server. The other downloads, the preview images and some upload formats need extra software on the server. The module detects what is installed and uses the first tool that works.</p><table tabindex="0"><thead><tr><th>Software</th><th>Used for</th><th>Install hint</th></tr></thead><tbody><tr><td>Inkscape 1.0+</td><td>PDF download, PNG previews, AI / EPS / PDF uploads</td><td><code>sudo apt install inkscape</code></td></tr><tr><td>Docker</td><td>Runs Inkscape in a container when Inkscape is not installed</td><td><a href="#using-docker">Using docker</a></td></tr><tr><td>Chromium / Google Chrome</td><td>Chrome PDF and Chrome PNG downloads</td><td><code>sudo apt install chromium</code></td></tr><tr><td>Ghostscript (<code>gs</code>)</td><td>CMYK PDF download</td><td><code>sudo apt install ghostscript</code></td></tr><tr><td>ImageMagick command line (<code>convert</code>, <code>magick</code>)</td><td>PNG previews (last fallback), HEIC uploads</td><td><code>sudo apt install imagemagick</code></td></tr><tr><td>PHP Imagick extension (<code>php-imagick</code>)</td><td>HEIC and AVIF uploads, without shell access</td><td><code>sudo apt install php-imagick</code>, then restart PHP-FPM or Apache</td></tr><tr><td>PHP GD with AVIF support</td><td>AVIF uploads</td><td>Included in PHP 8.1+ builds with AVIF enabled</td></tr><tr><td><code>heif-convert</code></td><td>HEIC uploads</td><td><code>sudo apt install libheif-examples</code></td></tr><tr><td><code>tifig</code></td><td>HEIC uploads (last fallback)</td><td><a href="https://github.com/monostream/tifig/releases" target="_blank" rel="noreferrer">tifig releases</a></td></tr><tr><td>Remote converter (paid API)</td><td>PDF, Chrome PDF and PNG previews when nothing is installed</td><td><a href="#using-the-remote-converter-paid-api">Remote converter</a></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>All command line tools need the PHP <code>shell_exec</code> function to be enabled, and the binary must be in the <code>PATH</code> of the web server user. The module also looks in <code>/usr/local/bin</code> and <code>/opt/homebrew/bin</code>.</p></div><div class="tip custom-block"><p class="custom-block-title">Imagick vs ImageMagick</p><p>The PHP Imagick extension and the ImageMagick command line tools are installed separately. The extension runs inside PHP and doesn&#39;t need <code>shell_exec</code>. HEIC needs ImageMagick built with HEIC support, and AVIF needs it built with AVIF support. To check that the extension is loaded:</p><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> imagick</span></span></code></pre></div></div><h3 id="fallback-order" tabindex="-1">Fallback order <a class="header-anchor" href="#fallback-order" aria-label="Permalink to “Fallback order”">​</a></h3><table tabindex="0"><thead><tr><th>Feature</th><th>Tools tried, in order</th></tr></thead><tbody><tr><td>PDF download</td><td>Inkscape, Docker (<code>linuxserver/inkscape</code>), remote converter</td></tr><tr><td>CMYK PDF download</td><td>Same as PDF download, then Ghostscript converts the PDF to CMYK</td></tr><tr><td>Chrome PDF download</td><td><code>chromium</code>, <code>chromium-browser</code>, <code>google-chrome</code>, remote converter</td></tr><tr><td>Chrome PNG download</td><td><code>chromium</code>, <code>chromium-browser</code>, <code>google-chrome</code></td></tr><tr><td>PNG previews</td><td>Inkscape, Docker (<code>uvarc/inkscape:1.0</code>), remote converter, ImageMagick <code>convert</code></td></tr><tr><td>AI / EPS / PDF uploads</td><td>Inkscape, Docker (<code>uvarc/inkscape:1.0</code>)</td></tr><tr><td>HEIC uploads</td><td>PHP Imagick extension, <code>heif-convert</code>, ImageMagick (<code>magick</code>, then <code>convert</code>), <code>tifig</code></td></tr><tr><td>AVIF uploads</td><td>PHP GD, PHP Imagick extension</td></tr></tbody></table><p>If no tool works for PNG previews, the module keeps the SVG preview.</p><h2 id="pdf-download" tabindex="-1">PDF Download <a class="header-anchor" href="#pdf-download" aria-label="Permalink to “PDF Download”">​</a></h2><p>To be able to download PDF files directly from the backoffice, you need to install <code>inkscape 1.0</code> or newer on your server.</p><p>The reason for requiring inkscape 1.0 or newer, is that it&#39;s the only version of inkscape that supports SVG embedded fonts.</p><h3 id="inkscape-installation" tabindex="-1">Inkscape installation <a class="header-anchor" href="#inkscape-installation" aria-label="Permalink to “Inkscape installation”">​</a></h3><p>To install inkscape, you need access to a terminal to allow you to execute the following commands.</p><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> inkscape</span></span></code></pre></div><p>Then check the inkscape version like this</p><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">inkscape</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># The version should be something like this:</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Inkscape 1.0.1 (3bc2e813f5, 2020-09-07)</span></span></code></pre></div><p>Please ask your hosting service or webmaster for assistance regarding the installation of inkscape on the server.</p><h4 id="using-docker" tabindex="-1">Using docker <a class="header-anchor" href="#using-docker" aria-label="Permalink to “Using docker”">​</a></h4><p>If you can&#39;t install inkscape 1.0 on your system, try using it from a docker container.</p><p>The module will pull these images in the background:</p><ul><li><code>linuxserver/inkscape</code> for the PDF download</li><li><code>uvarc/inkscape:1.0</code> for PNG previews and AI / EPS / PDF uploads</li></ul><p>The command that the module will execute for the PDF download is roughly:</p><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/html/designer:/var/www/html/designer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> linuxserver/inkscape</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/bin/inkscape</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/var/www/html/designer/designer/output/18-design18/0-side0/design-18-0.svg&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --export-type=pdf</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># /var/www/html/designer being the PrestaShop root dir in this case</span></span></code></pre></div><p>You can pull the images in advance to avoid a slow first download:</p><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> linuxserver/inkscape</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uvarc/inkscape:1.0</span></span></code></pre></div><p>If you get a permission error, try adding the <code>www-data</code> user to the <code>docker</code> group.</p><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usermod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -aG</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> www-data</span></span></code></pre></div><h3 id="using-chrome-chromium" tabindex="-1">Using Chrome / Chromium <a class="header-anchor" href="#using-chrome-chromium" aria-label="Permalink to “Using Chrome / Chromium”">​</a></h3><p>The Chrome PDF and Chrome PNG downloads use a headless Chromium or Google Chrome to convert the SVG files. The module looks for these binaries, in this order: <code>chromium</code>, <code>chromium-browser</code>, <code>google-chrome</code>.</p><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chromium</span></span></code></pre></div><p>If no browser is found, the Chrome PDF download falls back to the remote converter.</p><h3 id="cmyk-pdf" tabindex="-1">CMYK PDF <a class="header-anchor" href="#cmyk-pdf" aria-label="Permalink to “CMYK PDF”">​</a></h3><p>The CMYK PDF download first creates the PDF (see above), then converts it to CMYK with Ghostscript.</p><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ghostscript</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><h3 id="using-the-remote-converter-paid-api" tabindex="-1">Using the remote converter (Paid API) <a class="header-anchor" href="#using-the-remote-converter-paid-api" aria-label="Permalink to “Using the remote converter (Paid API)”">​</a></h3><p>You can use my online converter to convert the SVG files to PDF or PNG. It&#39;s used only when the local tools fail. The CMYK PDF download still needs Ghostscript on your server.</p><p>Here are the steps to follow:</p><p>1- Make a subscription to the API by following this payment link: <a href="https://buy.stripe.com/aEUaGa1Mc327cww4gl" target="_blank" rel="noreferrer">💳 API Subscription</a></p><p>2- Add this line to the file <code>config/defines.inc.php</code></p><div class="language-php"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">define</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;_DSN_API_URL_&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;https://converter.prestalife.net/&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>Make sure to insert this line after the <code>&lt;?php</code> tag</p></div>`,53)]])}var S=e(h,[[`render`,x]]);export{m as __pageData,S as default};